$evidencia$::jsonb) AS x(tabla text,fila jsonb);
CREATE SCHEMA IF NOT EXISTS respaldo_pruebas;
REVOKE ALL ON SCHEMA respaldo_pruebas FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS respaldo_pruebas.reinicios(
 clave text PRIMARY KEY, fecha timestamptz NOT NULL DEFAULT now(), datos jsonb NOT NULL
);
ALTER TABLE respaldo_pruebas.reinicios ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON respaldo_pruebas.reinicios FROM PUBLIC,anon,authenticated;
DO $reinicio$
DECLARE
 t text; restantes jsonb; copia jsonb:='{}'; antes jsonb:='{}'; n bigint; esperado bigint;
 tablas text[]:=ARRAY['ordenes_produccion','items_orden','documentos','devoluciones_cliente',
 'liberaciones_aliados','no_conformes_aliados','liberaciones_no_conforme','devoluciones_produccion',
 'sobrantes_bodega','movimientos','admin_correcciones','lote_items','lotes','listas_empaque',
 'despacho_revisiones','empaque_solicitudes','seguimiento_entregas','reservas_despacho','despachos_oc'];
 borrado text[]:=ARRAY['reservas_despacho','documentos','devoluciones_cliente','liberaciones_aliados',
 'no_conformes_aliados','liberaciones_no_conforme','devoluciones_produccion','sobrantes_bodega',
 'movimientos','admin_correcciones','lote_items','lotes','listas_empaque','seguimiento_entregas',
 'despacho_revisiones','empaque_solicitudes','despachos_oc'];
 r record;
BEGIN
 IF nullif(current_setting('app.settings.project_ref',true),'') IS NOT NULL
 AND current_setting('app.settings.project_ref',true)<>'igfuafcekcpugpmsoqbe' THEN
  RAISE EXCEPTION 'Proyecto distinto de ORBILOQ-DEV. No se cambio nada.';
 END IF;
 IF EXISTS(SELECT 1 FROM respaldo_pruebas.reinicios WHERE clave='op-90006-20261015-v1') THEN
  RAISE EXCEPTION 'Reinicio ya ejecutado. No se elimina trabajo nuevo.';
 END IF;
 FOREACH t IN ARRAY tablas LOOP
  EXECUTE format('LOCK TABLE public.%I IN SHARE ROW EXCLUSIVE MODE',t);
 END LOOP;
 IF (SELECT count(*) FROM public.items_orden WHERE orden_id='657d55ef-1372-49ad-9312-bd5cdc3a6e28')<>2
 OR NOT EXISTS(SELECT 1 FROM public.ordenes_produccion WHERE id='657d55ef-1372-49ad-9312-bd5cdc3a6e28'
 AND numero_op='90006' AND cliente='CLIENTE PRUEBA B') THEN
  RAISE EXCEPTION 'La identidad o las tallas de la OP cambiaron.';
 END IF;
 -- Comparacion tipada: fechas, UUID y JSON se comparan como en la tabla real.
 FOREACH t IN ARRAY tablas LOOP
  SELECT count(*) INTO esperado FROM reinicio_90006_esperado WHERE tabla=t;
  EXECUTE format('SELECT count(*) FROM public.%I x WHERE EXISTS(
    SELECT 1 FROM reinicio_90006_esperado e WHERE e.tabla=$1
    AND to_jsonb(x)=to_jsonb(jsonb_populate_record(NULL::public.%I,e.fila)))',t,t) INTO n USING t;
  IF n<>esperado THEN RAISE EXCEPTION 'Cambios en %. Se requiere nuevo diagnostico; se revierte todo.',t; END IF;
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]''::jsonb)
    FROM public.%I x WHERE NOT EXISTS(SELECT 1 FROM reinicio_90006_esperado e WHERE e.tabla=$1
    AND to_jsonb(x)=to_jsonb(jsonb_populate_record(NULL::public.%I,e.fila)))',t,t) INTO restantes USING t;
  antes:=antes||jsonb_build_object(t,restantes);
  -- Un registro nuevo o de otra OP que mencione objetos afectados bloquea la limpieza.
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(restantes) x,
    reinicio_90006_esperado e WHERE e.fila->>'id' IS NOT NULL
    AND strpos(x::text,e.fila->>'id')>0) THEN
   RAISE EXCEPTION 'Dependencia nueva o compartida en %. No se borro nada.',t;
  END IF;
  copia:=copia||jsonb_build_object(t,coalesce((SELECT jsonb_agg(fila) FROM reinicio_90006_esperado WHERE tabla=t),'[]'::jsonb));
 END LOOP;
 -- No permitir cascadas hacia tablas no revisadas.
 FOR r IN SELECT c.conrelid::regclass::text tabla FROM pg_constraint c
 JOIN pg_class p ON p.oid=c.conrelid JOIN pg_namespace ns ON ns.oid=p.relnamespace
 WHERE c.contype='f' AND c.confrelid IN (SELECT ('public.'||x)::regclass FROM unnest(borrado) x)
 AND (ns.nspname<>'public' OR NOT (p.relname=ANY(tablas))) LOOP
  RAISE EXCEPTION 'Dependencia no revisada: %',r.tabla;
 END LOOP;
 INSERT INTO respaldo_pruebas.reinicios(clave,datos) VALUES('op-90006-20261015-v1',copia);
 FOREACH t IN ARRAY borrado LOOP
  EXECUTE format('DELETE FROM public.%I x WHERE EXISTS(SELECT 1 FROM reinicio_90006_esperado e
   WHERE e.tabla=$1 AND to_jsonb(x)=to_jsonb(jsonb_populate_record(NULL::public.%I,e.fila)))',t,t) USING t;
  GET DIAGNOSTICS n=ROW_COUNT;
  SELECT count(*) INTO esperado FROM reinicio_90006_esperado WHERE tabla=t;
  IF n<>esperado THEN RAISE EXCEPTION 'Conteo inesperado al limpiar %',t; END IF;
 END LOOP;
 -- Comparar tambien todos los registros no afectados: ningun cambio colateral.
 FOREACH t IN ARRAY tablas LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]''::jsonb)
   FROM public.%I x WHERE NOT EXISTS(SELECT 1 FROM reinicio_90006_esperado e WHERE e.tabla=$1
   AND to_jsonb(x)=to_jsonb(jsonb_populate_record(NULL::public.%I,e.fila)))',t,t) INTO restantes USING t;
  IF restantes IS DISTINCT FROM antes->t THEN RAISE EXCEPTION 'Cambio fuera de alcance en %. Se revierte todo.',t; END IF;
 END LOOP;
 FOREACH t IN ARRAY ARRAY['ordenes_produccion','items_orden'] LOOP
  EXECUTE format('SELECT count(*) FROM public.%I x WHERE EXISTS(SELECT 1 FROM reinicio_90006_esperado e
   WHERE e.tabla=$1 AND to_jsonb(x)=to_jsonb(jsonb_populate_record(NULL::public.%I,e.fila)))',t,t) INTO n USING t;
  SELECT count(*) INTO esperado FROM reinicio_90006_esperado WHERE tabla=t;
  IF n<>esperado THEN RAISE EXCEPTION 'La orden o sus tallas cambiaron. Se revierte todo.'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.vista_kardex WHERE numero_op='90006'
 AND (producido<>0 OR recibido<>0 OR despachado<>0 OR pendiente_reproceso<>0 OR pendiente_aliados<>0)) THEN
  RAISE EXCEPTION 'Saldos de OP 90006 no quedaron en cero. Se revierte todo.';
 END IF;
END $reinicio$;
COMMIT;
SELECT numero_op,codigo,talla,cantidad_pedida,producido,recibido,despachado,
 pendiente_reproceso,pendiente_aliados FROM public.vista_kardex WHERE numero_op='90006' ORDER BY talla;
-- Exportar este respaldo y conservarlo fuera de la base:
SELECT clave,fecha,datos FROM respaldo_pruebas.reinicios WHERE clave='op-90006-20261015-v1';
